mapper.select:
SELECT r.order_no, r.user_id, u.nick_name, r.spot_id, s.name AS spot_name, r.slot_date, r.slot_start, r.slot_end, r.quantity, r.total_amount, r.status, r.create_time FROM reserve r JOIN spot s ON s.id = r.spot_id JOIN `user` u ON u.id = r.user_id
AND r.spot_id = #{spotId}
AND r.status = #{status}
AND r.create_time >= #{startDate}
AND r.create_time < DATE_ADD(#{endDate}, INTERVAL 1 DAY)
ORDER BY r.create_time DESC, r.id DESC
